import{_ as c,C as o,o as n,c as s,j as e,a as d,E as a,ag as l}from"./chunks/framework.HG0H2VLS.js";const v=JSON.parse('{"title":"Toggle","description":"","frontmatter":{},"headers":[],"relativePath":"components/toggle.md","filePath":"components/toggle.md"}'),h={name:"components/toggle.md"},g={id:"toggle",tabindex:"-1"};function p(u,t,b,m,f,x){const r=o("Badge"),i=o("ComponentDemo");return n(),s("div",null,[t[3]||(t[3]=e("hr",null,null,-1)),t[4]||(t[4]=e("h2",{id:"title-toggle",tabindex:"-1"},[d("title: Toggle "),e("a",{class:"header-anchor",href:"#title-toggle","aria-label":'Permalink to "title: Toggle"'},"​")],-1)),e("h1",g,[t[0]||(t[0]=d("Toggle ",-1)),a(r,{type:"info",text:"Design System"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#toggle","aria-label":'Permalink to "Toggle <Badge type="info" text="Design System" />"'},"​",-1))]),t[5]||(t[5]=e("blockquote",null,[e("p",null,"On/off switch")],-1)),a(i,{src:"/demos/src/components/Toggle/Toggle.html"}),t[6]||(t[6]=l('<h2 id="variant-matrix" tabindex="-1">Variant matrix <a class="header-anchor" href="#variant-matrix" aria-label="Permalink to &quot;Variant matrix&quot;">​</a></h2><p>Two axes: <strong>Size</strong> × <strong>State</strong> = 12 variants.</p><table tabindex="0"><thead><tr><th>Size</th><th>Initial</th><th>Active</th><th>Disabled</th><th>Track w×h</th><th>Thumb</th></tr></thead><tbody><tr><td>xs</td><td><code>2025:1081</code></td><td><code>2025:1095</code></td><td><code>2025:1088</code></td><td>32×16</td><td>12</td></tr><tr><td>SM (default)</td><td><code>2702:2223</code></td><td><code>2702:2230</code></td><td><code>2702:2237</code></td><td>40×20</td><td>16</td></tr><tr><td>Default</td><td><code>2025:1102</code></td><td><code>2025:1116</code></td><td><code>2025:1109</code></td><td>44×24</td><td>20</td></tr><tr><td>LG</td><td><code>2025:1123</code></td><td><code>2025:1137</code></td><td><code>2025:1130</code></td><td>56×28</td><td>24</td></tr></tbody></table><p>SM is the implicit default (no CSS modifier). Other sizes via <code>.toggle--xs</code>, <code>.toggle--default</code>, <code>.toggle--lg</code>.</p><hr><h2 id="css-class-mapping" tabindex="-1">CSS class mapping <a class="header-anchor" href="#css-class-mapping" aria-label="Permalink to &quot;CSS class mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td>Wrapper</td><td><code>.toggle</code> (<code>&lt;button role=&quot;switch&quot;&gt;</code>)</td></tr><tr><td>Size=xs</td><td><code>.toggle--xs</code></td></tr><tr><td>Size=SM</td><td>(no modifier — default)</td></tr><tr><td>Size=Default</td><td><code>.toggle--default</code></td></tr><tr><td>Size=LG</td><td><code>.toggle--lg</code></td></tr><tr><td>State=Initial</td><td>(no modifier)</td></tr><tr><td>State=Active</td><td><code>.toggle--active</code></td></tr><tr><td>State=Disabled</td><td><code>.toggle--disabled</code> (with <code>aria-disabled</code>)</td></tr><tr><td>Toggle track</td><td><code>.toggle__track</code></td></tr><tr><td>Toggle thumb</td><td><code>.toggle__knob</code></td></tr><tr><td>Label &amp; Helper wrapper</td><td><code>.toggle__label</code></td></tr><tr><td>Label text</td><td><code>.toggle__label-text</code></td></tr><tr><td>Helper text</td><td><code>.toggle__helper</code></td></tr></tbody></table><hr><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><h3 id="wrapper" tabindex="-1">Wrapper <a class="header-anchor" href="#wrapper" aria-label="Permalink to &quot;Wrapper&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Token</th></tr></thead><tbody><tr><td>Gap</td><td><code>var(--ai-spacing-3)</code> (8px)</td></tr><tr><td>Padding (vertical)</td><td><code>1px</code> (raw — sub-token optical)</td></tr></tbody></table><h3 id="track-thumb-all-sizes" tabindex="-1">Track / thumb (all sizes) <a class="header-anchor" href="#track-thumb-all-sizes" aria-label="Permalink to &quot;Track / thumb (all sizes)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Token</th></tr></thead><tbody><tr><td>Track bg (Initial / Disabled)</td><td><code>var(--ai-border-secondary)</code></td></tr><tr><td>Track bg (Active)</td><td><code>var(--ai-surface-brand)</code> — was <code>--ai-chat-brand</code>; switched on 2026-05-27 per the new Dropdown user-menu Figma spec. StyleSettings contextually overrides back to <code>--ai-chat-brand</code>.</td></tr><tr><td>Track radius</td><td><code>var(--ai-radius-full)</code></td></tr><tr><td>Thumb bg</td><td><code>var(--ai-surface-primary)</code></td></tr><tr><td>Thumb radius</td><td><code>var(--ai-radius-full)</code></td></tr><tr><td>Thumb position (Initial)</td><td><code>top: 2px; left: 2.5px</code> (raw — sub-token optical)</td></tr><tr><td>Thumb position (Active)</td><td><code>left: calc(100% - thumb-w - 2.5px)</code></td></tr></tbody></table><h3 id="per-size-dimensions" tabindex="-1">Per-size dimensions <a class="header-anchor" href="#per-size-dimensions" aria-label="Permalink to &quot;Per-size dimensions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Size</th><th>Track w</th><th>Track h</th><th>Thumb</th></tr></thead><tbody><tr><td>xs</td><td><code>var(--ai-spacing-7)</code> (32px)</td><td><code>var(--ai-spacing-5)</code> (16px)</td><td><code>var(--ai-spacing-4)</code> (12px)</td></tr><tr><td>SM</td><td><code>var(--ai-spacing-8)</code> (40px)</td><td><code>20px</code> (raw)</td><td><code>var(--ai-spacing-5)</code> (16px)</td></tr><tr><td>Default</td><td><code>44px</code> (raw)</td><td><code>var(--ai-spacing-6)</code> (24px)</td><td><code>20px</code> (raw)</td></tr><tr><td>LG</td><td><code>var(--ai-spacing-10)</code> (56px)</td><td><code>28px</code> (raw)</td><td><code>var(--ai-spacing-6)</code> (24px)</td></tr></tbody></table><h3 id="label-helper" tabindex="-1">Label / helper <a class="header-anchor" href="#label-helper" aria-label="Permalink to &quot;Label / helper&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>xs / SM</th><th>Default / LG</th></tr></thead><tbody><tr><td>Label font-family</td><td><code>var(--ai-font-title)</code></td><td>(same)</td></tr><tr><td>Label font-weight</td><td><code>var(--ai-font-medium)</code></td><td><code>var(--ai-font-regular)</code></td></tr><tr><td>Label font-size</td><td><code>var(--ai-font-fixed-xs)</code> (14px)</td><td><code>var(--ai-font-fixed-sm)</code> (16px)</td></tr><tr><td>Label line-height</td><td><code>1.25</code></td><td>(same)</td></tr><tr><td>Label colour</td><td><code>var(--ai-text-primary)</code></td><td>(same)</td></tr><tr><td>Helper font-weight</td><td><code>var(--ai-font-regular)</code></td><td>(same)</td></tr><tr><td>Helper font-size</td><td><code>var(--ai-font-fixed-2xs)</code> (12px)</td><td><code>var(--ai-font-fixed-xs)</code> (14px)</td></tr><tr><td>Helper line-height</td><td><code>1.5</code></td><td>(same)</td></tr><tr><td>Helper colour</td><td><code>var(--ai-text-contrast)</code></td><td>(same)</td></tr><tr><td>Disabled label / helper colour</td><td><code>var(--ai-icon-contrast)</code></td><td>(same)</td></tr></tbody></table><h3 id="focus" tabindex="-1">Focus <a class="header-anchor" href="#focus" aria-label="Permalink to &quot;Focus&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Token</th></tr></thead><tbody><tr><td>Outline</td><td><code>none</code></td></tr><tr><td>Box-shadow</td><td><code>0 0 0 1px var(--ai-surface-primary), 0 0 0 3px var(--ai-surface-brand-soft)</code> (on track)</td></tr></tbody></table><hr><h2 id="token-gaps" tabindex="-1">Token gaps <a class="header-anchor" href="#token-gaps" aria-label="Permalink to &quot;Token gaps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gap</th><th>Where</th><th>Resolution</th></tr></thead><tbody><tr><td>20px (SM track height)</td><td>SM size</td><td>Approved raw — sub-token optical</td></tr><tr><td>44px (Default track width)</td><td>Default size</td><td>Approved raw — sub-token optical</td></tr><tr><td>20px (Default thumb)</td><td>Default size</td><td>Approved raw — sub-token optical</td></tr><tr><td>28px (LG track height)</td><td>LG size</td><td>Approved raw — sub-token optical</td></tr><tr><td>2px / 2.5px (thumb offsets)</td><td>All sizes</td><td>Approved raw — sub-token optical</td></tr></tbody></table><p>These are all visual-detail values that don&#39;t fit the <code>--ai-spacing-*</code> scale. Same exception class as letter-spacing and border-widths.</p><hr><h2 id="cross-context-notes" tabindex="-1">Cross-context notes <a class="header-anchor" href="#cross-context-notes" aria-label="Permalink to &quot;Cross-context notes&quot;">​</a></h2><ul><li>The Toggle Active track colour switched from <code>--ai-chat-brand</code> to <code>--ai-surface-brand</code> on 2026-05-27 to align with the new Figma Dropdown User Menu spec. The Chat context (StyleSettings) preserves the original chat-brand colour via a contextual override scoped to <code>.style-settings</code>.</li></ul><hr><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><ul><li>The toggle is a <code>&lt;button role=&quot;switch&quot;&gt;</code> with <code>aria-checked=&quot;true|false&quot;</code>.</li><li>Disabled toggles get <code>aria-disabled=&quot;true&quot;</code> and the <code>.toggle--disabled</code> visual treatment (opacity + not-allowed cursor).</li><li>Icon-only toggles need <code>aria-label</code>; label-bearing toggles use the <code>.toggle__label-text</code> as the accessible name (via implicit labelling).</li></ul><hr><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-05-07 (approx): Initial Toggle built — Size=SM only, Active track <code>--ai-chat-brand</code>.</li><li>2026-05-27: Figma expanded to 4 sizes (xs, SM, Default, LG) and switched Active track to <code>--ai-surface-brand</code>. CSS updated to match; StyleSettings retains <code>--ai-chat-brand</code> via contextual override.</li></ul><h2 id="toggle-xxs-—-the-fifth-size-added-2026-08-25" tabindex="-1"><code>toggle--xxs</code> — the fifth size, added 2026-08-25 <a class="header-anchor" href="#toggle-xxs-—-the-fifth-size-added-2026-08-25" aria-label="Permalink to &quot;`toggle--xxs` — the fifth size, added 2026-08-25&quot;">​</a></h2><p>Added while building <strong>TableListing</strong> (<code>3488:196339</code>), whose &quot;Only free seats&quot; control is a Toggle instance at <code>size=&quot;xxs&quot;</code>.</p><p><strong>This is a real Figma variant, not an invention</strong> — Toggle&#39;s set (<code>2025:1080</code>) defines five sizes, and the component only had four:</p><table tabindex="0"><thead><tr><th>Figma Size</th><th>Node (Initial)</th><th>Track</th><th>Knob</th><th>In code</th></tr></thead><tbody><tr><td><strong>xxs</strong></td><td><code>2025:1081</code></td><td><strong>24×12</strong></td><td><strong>8×8</strong></td><td><strong><code>.toggle--xxs</code></strong> (new)</td></tr><tr><td>xs</td><td><code>3435:28258</code></td><td>32×16</td><td>12×12</td><td><code>.toggle--xs</code></td></tr><tr><td>SM</td><td><code>2702:2223</code></td><td>40×20</td><td>16×16</td><td>base <code>.toggle</code></td></tr><tr><td>Default</td><td><code>2025:1102</code></td><td>44×24</td><td>20×20</td><td><code>.toggle--default</code></td></tr><tr><td>LG</td><td><code>2025:1123</code></td><td>?×28</td><td>24×24</td><td><code>.toggle--lg</code></td></tr></tbody></table><p>Every xxs dimension is a token: 24 = <code>--ai-spacing-6</code>, 12 = <code>--ai-spacing-4</code>, 8 = <code>--ai-spacing-3</code>. Colours are the component&#39;s existing ones — <code>--ai-border-secondary</code> track, <code>--ai-surface-brand</code> when active — which is exactly what Figma binds. Verified 24×12 / 8×8 with the knob at 2.5px → 13.5px.</p><p><strong>xxs has only Initial and Active in Figma — no Disabled</strong>, so no Disabled row was added to the demo. The size-agnostic <code>--disabled</code> still composes if a consumer ever needs it.</p><p><strong>One deliberate 0.5px difference.</strong> Figma places the active knob at <code>left: 14px</code>, i.e. a 2px right inset against its own 2.5px left inset. Every other size in this component uses a symmetric <code>calc(100% - knob - 2.5px)</code>, which gives 13.5px here. Internal consistency was preferred over reproducing what reads as a Figma nudge; if the asymmetry is deliberate, this is the line to change.</p><h2 id="toggle-js-—-the-component-owns-its-own-flip-from-2026-08-26" tabindex="-1"><code>Toggle.js</code> — the component owns its own flip, from 2026-08-26 <a class="header-anchor" href="#toggle-js-—-the-component-owns-its-own-flip-from-2026-08-26" aria-label="Permalink to &quot;`Toggle.js` — the component owns its own flip, from 2026-08-26&quot;">​</a></h2><p>Toggle shipped <strong>CSS-only</strong> until now, which meant it did not work: a <code>role=&quot;switch&quot;</code> whose <code>aria-checked</code> never changes is a broken control. Every consumer had re-implemented the same three-line flip inline — <strong>nine copies</strong>:</p><table tabindex="0"><thead><tr><th>Page</th><th>Note</th></tr></thead><tbody><tr><td><code>Toggle.html</code></td><td>its own demo</td></tr><tr><td><code>Dropdown.html</code></td><td>commented &quot;so .toggle--active flips and the linked reveal fires&quot;</td></tr><tr><td><code>StyleSettings.html</code></td><td></td></tr><tr><td><code>TableListing.html</code></td><td>added the day before this landed</td></tr><tr><td><code>HeaderGroup.html</code></td><td>delegated, for toggles injected after parse</td></tr><tr><td><code>AiChat.html</code> ×2</td><td>flip <strong>plus</strong> side effects (borders, suggestions)</td></tr><tr><td><code>ControlHub.html</code></td><td>commented &quot;<strong>Toggle has no standalone JS file</strong>; consumers wire .toggle clicks inline&quot;</td></tr><tr><td><code>ControlScreen.html</code></td><td>same comment</td></tr></tbody></table><p>Two component JS files made it worse by <em>assuming</em> the behaviour existed: <code>Dropdown.js</code> and <code>HeaderGroup.js</code> both carry comments about &quot;the toggle&#39;s own click handler&quot;. Those comments are now true.</p><p><strong>Behaviour.</strong> Click flips <code>.toggle--active</code>, syncs <code>aria-checked</code>, then emits <code>toggle:change</code> (bubbles, <code>detail { active }</code>). <code>.toggle--disabled</code>, <code>aria-disabled=&quot;true&quot;</code> and a disabled <code>&lt;button&gt;</code> are inert. Keyboard is free — it is a real <code>&lt;button&gt;</code>, so Space and Enter fire click.</p><p><strong>Two design choices, both taken from what those nine copies had learned:</strong></p><ol><li><strong>Delegated at the document</strong>, not bound per element. Three of the nine had already converged on delegation because the user-menu Dropdown injects toggles after parse, which a <code>querySelectorAll</code> pass at <code>DOMContentLoaded</code> never sees.</li><li><strong>Capture phase.</strong> A delegated bubble listener runs <em>after</em> listeners on the element itself, so a consumer reading <code>.toggle--active</code> synchronously in its own handler would see the pre-click state. Capture runs document-first, so the flip is applied before any element handler reads it. <code>Dropdown.js</code> and <code>HeaderGroup.js</code> both hedge with a <code>setTimeout</code> for exactly that reason; they no longer need to, though the hedge is harmless and was left alone.</li></ol><p>Including the script twice is guarded and cannot double-flip.</p><h3 id="verified-after-the-change" tabindex="-1">Verified after the change <a class="header-anchor" href="#verified-after-the-change" aria-label="Permalink to &quot;Verified after the change&quot;">​</a></h3><p>All eight consumer pages: <strong>flips exactly once</strong> per click (not twice — the regression to fear when adding self-init while inline copies remain), two <code>toggle:change</code> events for two clicks, and disabled toggles inert. Side effects that used to live in the flip handlers still work:</p><ul><li><strong>AiChat</strong> — <code>chat-header--no-border</code> and the suggestions row, both directions. These are the two handlers that were converted to <code>toggle:change</code> listeners rather than deleted.</li><li><strong>Dropdown</strong> and <strong>HeaderGroup</strong> — reveal rows (<code>data-reveal-by</code>) sync, <code>SYNCED=true</code>.</li><li><strong>HeaderGroup</strong> — the icon-nav group class syncs.</li></ul><blockquote><p><strong>Test over HTTP, not <code>file://</code>.</strong> AiChat, Dropdown, ControlHub and ControlScreen load <code>Dropdown.js</code> as an ES module, and modules are blocked over <code>file://</code> — the module never runs, so every listener in it silently fails to attach. Verifying AiChat&#39;s side effects on <code>file://</code> showed them dead when they were fine; <code>python3 -m http.server</code> was needed to see the truth.</p></blockquote><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=2025-1080" target="_blank" rel="noreferrer">Open in Figma</a></p>',53))])}const y=c(h,[["render",p]]);export{v as __pageData,y as default};
